const oldFile = {
  contents: "export function greet(name: string) {\n  return `Hello, ${name}`;\n}\n",
  name: "greeting.ts",
};

const newFile = {
  contents:
    'export function greet(name: string = "world") {\n  const greeting = `Welcome, ${name}!`;\n  return greeting;\n}\n',
  name: "greeting.ts",
};

export { oldFile, newFile };

import { useState } from "react";
import { DiffView } from "@/registry/erbium/blocks/diff-view";
import { ToggleGroup, ToggleGroupItem } from "@/registry/erbium/ui/toggle-group";
import { Toggle } from "@/registry/erbium/ui/toggle";
import { oldFile, newFile } from "../examples/files";

const Example = () => {
  const [layout, setLayout] = useState<"split" | "unified">("split");
  const [wrap, setWrap] = useState(false);

  return (
    <div className="grid w-full max-w-4xl gap-4">
      <div className="flex flex-wrap items-center gap-3">
        <ToggleGroup
          aria-label="Diff layout"
          value={[layout]}
          onValueChange={(values) => {
            const value = values[0];

            if (value === "split" || value === "unified") {
              setLayout(value);
            }
          }}
          size="sm"
          variant="outline"
        >
          <ToggleGroupItem value="split">Split</ToggleGroupItem>
          <ToggleGroupItem value="unified">Unified</ToggleGroupItem>
        </ToggleGroup>
        <Toggle pressed={wrap} onPressedChange={setWrap} size="sm" variant="outline">
          Wrap lines
        </Toggle>
      </div>
      <DiffView
        oldFile={oldFile}
        newFile={newFile}
        options={{ diffStyle: layout, overflow: wrap ? "wrap" : "scroll" }}
      />
    </div>
  );
};

export default Example;
